sp_widget.client_script:
function($scope, spUtil, $rootScope) {
    var c = this;

    // 🔄 Atualiza quando outro widget dispara o evento de log de acesso
    $rootScope.$on('portal_access_logged', function(event, data) {
        spUtil.refresh($scope);
    });

    // 👤 Garante dados para o visitante anônimo
    if (!c.data.isLoggedIn && (!c.data.accesses || c.data.accesses.length === 0)) {
        var anonymousId = localStorage.getItem('sn_portal_anonymous_id');
        console.log('Pekas>>> Anon ID no localStorage:', anonymousId);

        if (anonymousId) {
            // Consulta o servidor enviando o anonId
            c.server.get({ anonId: anonymousId }).then(function(response) {
                console.log('Pekas>>> Dados recebidos do servidor:', response);

                // Atualiza a lista de acessos com os dados do servidor
                if (response && response.data && response.data.accesses) {
                    c.data.accesses = response.data.accesses;
                    $scope.$applyAsync(); // força renderização Angular
                    console.log('Pekas>>> Lista atualizada com', c.data.accesses.length, 'registros.');
                } else {
                    console.warn('Pekas>>> Nenhum dado retornado do servidor.');
                }
            }).catch(function(err) {
                console.error('Pekas>>> Erro ao consultar servidor:', err);
            });
        } else {
            console.warn('Pekas>>> Nenhum ID anônimo encontrado no localStorage.');
        }
    } else {
        console.log('Pekas>>> Usuário logado ou já possui acessos em cache.');
    }
}

sp_widget.script:
(function() {
    // 🧩 FUNÇÃO AUXILIAR DE FORMATAÇÃO
    function formatPageId(id) {
        if (!id) return 'Página Inicial';
        var formatted = id.replace(/_/g, ' ');
        formatted = formatted.toLowerCase().replace(/\b(\w)/g, function(s) { return s.toUpperCase(); });
        return formatted;
    }

    // 🧩 VARIÁVEIS INICIAIS
    var TABLE_NAME = 'x_sded9_portal_t_0_acessos_do_portal';
    data.isLoggedIn = gs.isLoggedIn();
    data.accesses = [];

    var currentIdentifier = gs.isLoggedIn() ? gs.getUserID() : null;
    var queryField = 'u_usuario';

    // 🧩 LOG DE DEBUG
    gs.info('Pekas>>> Execução do Server Script | Usuário logado: ' + gs.isLoggedIn() + ' | user=' + gs.getUserName());

    // 🧩 SEGURANÇA: verifica se input existe antes de tentar acessar
    if (!data.isLoggedIn) {
        if (typeof input !== 'undefined' && input && input.anonId) {
            currentIdentifier = input.anonId;
            queryField = 'u_anonimo_id';
            gs.info('Pekas>>> ID anônimo recebido: ' + input.anonId);
        } else {
            gs.info('Pekas>>> Nenhum anonId recebido do client.');
        }
    }

    if (currentIdentifier && queryField) {
    var grAccess = new GlideRecord(TABLE_NAME);
    grAccess.addQuery(queryField, currentIdentifier);
    grAccess.orderByDesc('u_hora_do_acesso');
    grAccess.setLimit(6);
    grAccess.query();

    var count = 0;
    while (grAccess.next()) {
        count++;
        var pageUrlId = grAccess.u_pagina_url.toString();

        data.accesses.push({
            page_id: pageUrlId,
            page_display_name: formatPageId(pageUrlId),
            time: grAccess.u_hora_do_acesso.getDisplayValue(),
            time_ago: ''
        });
    }

    gs.info('Pekas>>> Registros encontrados: ' + count + ' | QueryField=' + queryField + ' | Identifier=' + currentIdentifier);
} else {
    gs.info('Pekas>>> Nenhum identificador definido (provável execução inicial sem input).');
}

var session = gs.getSession();
var addr = session.getClientIP();
gs.info("IP Pekas>> " + addr);

})();
